CREATE TABLE device_timelines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid NOT NULL, user_id varchar(64) NOT NULL, event_type varchar(16) NOT NULL CHECK (event_type IN ('CREATED','UPDATED','MAINTENANCE','WARRANTY','DISPOSED')), event_date date NOT NULL, title varchar(64) NOT NULL, description varchar(256), payload jsonb CHECK (payload IS NULL OR jsonb_typeof(payload) = 'object'), created_at timestamptz NOT NULL DEFAULT now());
